import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv } from 'three/tsl';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Vector3
  } = THREE;

  const root = new Group();
  root.name = config.name || 'collection-title';

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const createdGeometries = [];
  const createdMaterials = [];
  const ownedTextures = [];
  const primitiveCleanups = [];

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    createdMaterials.push(material);
    return material;
  };

  const makeMesh = (geometry, material, name) => {
    createdGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    if (name) mesh.name = name;
    return mesh;
  };

  const gradientStops = visualSpec.gradientStops ?? [
    colors.surface,
    colors.ink,
    colors.surface
  ];

  const stopColor = (stop, fallback) => {
    if (typeof stop === 'string') return stop;
    if (stop && typeof stop.color === 'string') return stop.color;
    return fallback;
  };

  const gradientStart = stopColor(gradientStops[0], colors.surface);
  const gradientEnd = stopColor(
    gradientStops[gradientStops.length - 1],
    colors.ink
  );

  const backdropMaterial = makeBasicMaterial();
  const backdropY = uv().y;
  const backdropT = smoothstep(0.0, 1.0, backdropY);
  backdropMaterial.colorNode = mix(
    color(gradientStart),
    color(gradientEnd),
    backdropT
  );

  const backdrop = makeMesh(
    new PlaneGeometry(7, 6),
    backdropMaterial,
    'engineered-gradient-backdrop'
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const lowerWashMaterial = makeBasicMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.7,
    depthWrite: false
  });
  const lowerWash = makeMesh(
    new PlaneGeometry(7, 1.45),
    lowerWashMaterial,
    'lower-surface-plane'
  );
  lowerWash.position.set(0, -2.28, -2.35);
  root.add(lowerWash);

  const shadowMaterial = makeBasicMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.52,
    depthWrite: false
  });
  const shadow = makeMesh(
    new THREE.CircleGeometry(2.55, 64),
    shadowMaterial,
    'contact-shadow'
  );
  shadow.scale.set(1.75, 0.24, 1);
  shadow.position.set(0.12, -1.27, -1.55);
  root.add(shadow);

  const frameMaterial = makeBasicMaterial({
    color: colors.paper
  });
  const frame = makeMesh(
    new PlaneGeometry(5.55, 3.52),
    frameMaterial,
    'paper-image-frame'
  );
  frame.position.set(0, -0.08, -1.22);
  root.add(frame);

  const imageMaterial = makeBasicMaterial({
    color: colors.paper,
    transparent: true
  });
  const image = makeMesh(
    new PlaneGeometry(5.3, 3.27),
    imageMaterial,
    'collection-image'
  );
  image.position.set(0, -0.08, -1.05);
  root.add(image);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (root.userData.cleaned) {
        texture.dispose();
        return;
      }

      ownedTextures.push(texture);

      if (THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const accentMaterial = makeBasicMaterial({
    color: colors.accent
  });

  const accentBar = makeMesh(
    new BoxGeometry(0.075, 3.42, 0.035),
    accentMaterial,
    'signal-red-accent'
  );
  accentBar.position.set(-2.73, -0.08, -0.9);
  root.add(accentBar);

  const accentTick = makeMesh(
    new BoxGeometry(0.72, 0.075, 0.04),
    accentMaterial,
    'signal-red-tick'
  );
  accentTick.position.set(2.02, -1.67, -0.88);
  root.add(accentTick);

  const items = config.textContent ?? visualSpec.textContent ?? [];

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: item.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.name = item.role
      ? `text-${item.role}`
      : 'collection-title-text';

    textObject.position.set(-2.42, 1.62, -0.62);
    root.add(textObject);
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive?.name) continue;

    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params ?? {});
    if (result && typeof result.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.handlers = {};
  root.userData.cleaned = false;
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const cleanup of primitiveCleanups) {
      try {
        cleanup();
      } catch (_) {}
    }

    for (const texture of ownedTextures) {
      texture.dispose();
    }

    for (const material of createdMaterials) {
      material.dispose();
    }

    for (const geometry of createdGeometries) {
      geometry.dispose();
    }

    root.clear();
  };

  return root;
}

export default createNode;
